<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Ubuntu Desktop</title>
<style>
*{box-sizing:border-box;margin:0;padding:0}
html,body{height:100%;overflow:hidden;font-family:"Ubuntu","Segoe UI",Cantorell,sans-serif;background:#1a0a14;color:#eee}
#desktop{position:fixed;inset:0;width:100vw;height:100vh;overflow:hidden;background:linear-gradient(135deg,#2c001e 0%,#3d0f2e 25%,#5e2750 50%,#772953 65%,#a34a28 85%,#e95420 100%);display:flex;flex-direction:column}
#topbar{height:32px;background:rgba(0,0,0,0.92);display:flex;align-items:center;justify-content:space-between;padding:0 14px;font-size:13px;color:#fff;z-index:1000;user-select:none;flex-shrink:0}
#topbar .left,#topbar .right{display:flex;align-items:center;gap:14px}
#topbar .pill{cursor:default;opacity:.95}
#topbar .dot{width:8px;height:8px;border-radius:50%;background:#e95420;display:inline-block;margin-right:6px;vertical-align:middle}
#clock{font-variant-numeric:tabular-nums}
#main{flex:1;display:flex;position:relative;overflow:hidden}
#taskbar{width:64px;background:rgba(20,10,15,0.72);backdrop-filter:blur(10px);border-right:1px solid rgba(255,255,255,0.08);display:flex;flex-direction:column;align-items:center;padding:10px 0;gap:10px;z-index:900;flex-shrink:0}
#taskbar button{width:48px;height:48px;border-radius:12px;border:1px solid transparent;background:rgba(255,255,255,0.06);font-size:24px;cursor:pointer;display:flex;align-items:center;justify-content:center;transition:all .15s;color:#fff}
#taskbar button:hover{background:rgba(255,255,255,0.18);transform:scale(1.05)}
#taskbar button.active{background:rgba(233,84,32,0.35);border-color:rgba(233,84,32,0.6)}
