#wallpaper{flex:1;position:relative;overflow:hidden}
.desktop-icons{position:absolute;top:16px;left:16px;display:flex;flex-direction:column;gap:18px;z-index:1}
.dicon{width:84px;text-align:center;font-size:12px;color:#fff;cursor:pointer;padding:8px 4px;border-radius:8px;border:1px solid transparent}
.dicon:hover{background:rgba(255,255,255,0.12)}
.dicon .big{font-size:36px;display:block;margin-bottom:4px}
.window{position:absolute;top:40px;left:90px;width:640px;height:440px;min-width:360px;min-height:240px;background:#2b2b2b;border-radius:12px 12px 10px 10px;box-shadow:0 24px 70px rgba(0,0,0,0.6),0 0 0 1px rgba(255,255,255,0.12);display:flex;flex-direction:column;overflow:hidden;z-index:10}
.window.focused{box-shadow:0 24px 80px rgba(0,0,0,0.75),0 0 0 1px rgba(233,84,32,0.5)}
.win-header{height:38px;background:linear-gradient(#3d3d3d,#2e2e2e);display:flex;align-items:center;justify-content:space-between;padding:0 8px 0 14px;cursor:grab;user-select:none;flex-shrink:0;border-bottom:1px solid rgba(0,0,0,0.6)}
.win-header:active{cursor:grabbing}
.win-title{font-size:13px;font-weight:600;color:#eee;display:flex;align-items:center;gap:8px}
.win-controls{display:flex;gap:6px;align-items:center}
.win-controls button{width:26px;height:26px;border-radius:50%;border:none;cursor:pointer;font-size:13px;line-height:1;display:flex;align-items:center;justify-content:center;color:#fff}
.win-min{background:#767676}.win-max{background:#2e9e4a}.win-close{background:#e95420;font-weight:bold}
.win-min:hover,.win-max:hover,.win-close:hover{filter:brightness(1.2)}
.win-body{flex:1;display:flex;min-height:0;background:#1e1e1e}
#files-window .win-body{flex-direction:row}
#files-sidebar{width:150px;background:#252525;border-right:1px solid #111;padding:10px 6px;display:flex;flex-direction:column;gap:2px;flex-shrink:0}
#files-sidebar button{background:transparent;border:none;color:#ddd;text-align:left;padding:8px 10px;border-radius:6px;font-size:13px;cursor:pointer}
#files-sidebar button:hover,#files-sidebar button.sel{background:#3d3d3d;color:#fff}
#files-main{flex:1;display:flex;flex-direction:column;min-width:0;background:#1e1e1e}
#files-toolbar{display:flex;align-items:center;gap:8px;padding:8px 10px;background:#2e2e2e;border-bottom:1px solid #111}
#files-up,#files-home,#files-refresh{background:#3d3d3d;color:#fff;border:1px solid #555;border-radius:6px;padding:5px 10px;font-size:13px;cursor:pointer}
#files-up:hover,#files-home:hover,#files-refresh:hover{background:#4d4d4d}
#files-path{flex:1;background:#111;color:#fff;border:1px solid #444;border-radius:6px;padding:6px 10px;font-size:13px;font-family:monospace;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#files-list{flex:1;overflow:auto;padding:12px;display:grid;grid-template-columns:repeat(auto-fill,minmax(90px,1fr));gap:8px;align-content:start;min-height:120px}
.fs-item{background:rgba(255,255,255,0.04);border:1px solid transparent;border-radius:8px;padding:12px 6px 10px;text-align:center;font-size:13px;color:#eee;cursor:pointer;user-select:none;min-height:64px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;word-break:break-all}
.fs-item::before{font-size:28px;line-height:1}
.fs-item[data-type="dir"]::before{content:"📁"}
.fs-item[data-type="file"]::before{content:"📄"}
.fs-item:hover{background:rgba(255,255,255,0.1)}
.fs-item.selected{background:rgba(233,84,32,0.3);border-color:rgba(233,84,32,0.6)}
#files-status{padding:6px 12px;font-size:12px;color:#aaa;background:#252525;border-top:1px solid #111}
#notepad-window .win-body{flex-direction:column}
#notepad-toolbar{display:flex;align-items:center;gap:8px;padding:8px 10px;background:#2e2e2e;border-bottom:1px solid #111}
#new-tab{background:#e95420;color:#fff;border:none;border-radius:6px;padding:6px 12px;font-size:13px;cursor:pointer;font-weight:600}
#new-tab:hover{background:#f56a3a}
#notepad-status{font-size:12px;color:#aaa;margin-left:auto}
#tabs{display:flex;gap:4px;padding:8px 8px 0;background:#252525;overflow-x:auto;flex-shrink:0;border-bottom:1px solid #111}
.tab{background:#3a3a3a;color:#ddd;border:1px solid #111;border-bottom:none;border-radius:8px 8px 0 0;padding:7px 8px 7px 12px;font-size:13px;cursor:pointer;display:flex;align-items:center;gap:8px;white-space:nowrap;max-width:180px;user-select:none}
.tab.active{background:#1e1e1e;color:#fff;font-weight:600}
.tab:hover{background:#4a4a4a}.tab.active:hover{background:#1e1e1e}
.tab .tab-close{background:transparent;border:none;color:#aaa;font-size:14px;cursor:pointer;border-radius:4px;padding:0 4px;line-height:1}
.tab .tab-close:hover{background:#e95420;color:#fff}
#editor{flex:1;min-height:150px;background:#1e1e1e;color:#f0f0f0;border:none;outline:none;resize:none;padding:14px;font-size:14px;line-height:1.6;font-family:"Ubuntu Mono",Consolas,monospace;width:100%}
#editor:focus{background:#211e1e}
.context-hint{position:absolute;bottom:12px;right:14px;font-size:12px;color:rgba(255,255,255,0.75);background:rgba(0,0,0,0.45);padding:6px 10px;border-radius:6px;z-index:1;pointer-events:none}
@media(max-width:700px){.window{left:10px!important;top:10px!important;width:calc(100% - 20px)!important}}
</style>
</head>
<body>
<div id="desktop">
  <div id="topbar">
    <div class="left"><span class="pill"><span class="dot"></span>Activities</span><span class="pill">Files</span><span class="pill">Notepad</span></div>
    <div class="pill" id="clock">--:--</div>
    <div class="right"><span class="pill">🔊</span><span class="pill">📶</span><span class="pill">🔋</span><span class="pill">⏻</span></div>
  </div>
  <div id="main">
    <div id="taskbar">
      <button id="open-files" title="Files">📁</button>
      <button id="open-notepad" title="Notepad">📝</button>
      <div class="sep"></div>
      <div class="hint">Dock<br>click<br>to open</div>
    </div>
    <div id="wallpaper">
      <div class="desktop-icons">
        <div class="dicon" id="desk-files"><span class="big">📁</span>Files</div>
        <div class="dicon" id="desk-notes"><span class="big">📝</span>Notepad</div>
      </div>
      <div class="context-hint">Double-click folders to open • Drag windows by title bar</div>

      <div id="files-window" class="window" style="display:none" role="dialog" aria-label="Files">
        <div class="win-header">
          <div class="win-title">📁 Files</div>
          <div class="win-controls">
            <button class="win-min" title="Minimize">−</button>
            <button class="win-max" title="Maximize">□</button>
            <button class="win-close" title="Close">×</button>
          </div>
        </div>
        <div class="win-body">
          <div id="files-sidebar">
            <button data-go="/">🏠 Root</button>
            <button data-go="/home/user">👤 Home</button>
            <button data-go="/home/user/Documents">📄 Documents</button>
            <button data-go="/home/user/Downloads">⬇ Downloads</button>
            <button data-go="/home/user/Pictures">🖼 Pictures</button>
          </div>
          <div id="files-main">
            <div id="files-toolbar">
              <button id="files-up" title="Go to parent folder">↑ Up</button>
              <button id="files-home" title="Go home">Home</button>
              <button id="files-refresh" title="Refresh">⟳</button>
              <div id="files-path">/</div>
            </div>
            <div id="files-list"></div>
            <div id="files-status">Ready</div>
          </div>
        </div>
      </div>

      <div id="notepad-window" class="window" style="display:none;left:140px;top:70px" role="dialog" aria-label="Notepad">
        <div class="win-header">
          <div class="win-title">📝 Notepad</div>
          <div class="win-controls">
            <button class="win-min" title="Minimize">−</button>
            <button class="win-max" title="Maximize">□</button>
            <button class="win-close" title="Close">×</button>
          </div>
        </div>
        <div class="win-body">
          <div id="notepad-toolbar">
            <button id="new-tab">+ New Tab</button>
            <span id="notepad-status">Saved</span>
          </div>
          <div id="tabs"></div>
          <textarea id="editor" placeholder="Start typing..."></textarea>
        </div>
      </div>

    </div>
  </div>
</div>
<script>
(function(){
var zTop=20;
function bringToFront(el){zTop++;el.style.zIndex=zTop;document.querySelectorAll('.window').forEach(function(w){w.classList.remove('focused')});el.classList.add('focused');}
function showWin(el){el.style.display='flex';bringToFront(el);}
function hideWin(el){el.style.display='none';}
document.querySelectorAll('.window').forEach(function(w){
  w.addEventListener('mousedown',function(){bringToFront(w)});
  var c=w.querySelector('.win-close'); if(c){c.addEventListener('click',function(e){e.stopPropagation();hideWin(w);syncTaskbar();});}
  var m=w.querySelector('.win-min'); if(m){m.addEventListener('click',function(e){e.stopPropagation();hideWin(w);syncTaskbar();});}
  var mx=w.querySelector('.win-max'); if(mx){mx.addEventListener('click',function(e){
    e.stopPropagation();bringToFront(w);
    if(w.dataset.max==='1'){w.dataset.max='';w.style.top=w._t||'40px';w.style.left=w._l||'90px';w.style.width=w._w||'640px';w.style.height=w._h||'440px';}
    else{w._t=w.style.top;w._l=w.style.left;w._w=w.style.width;w._h=w.style.height;w.dataset.max='1';w.style.top='0';w.style.left='0';w.style.width='100%';w.style.height='100%';w.style.borderRadius='0';if(w._t!=='0')w.style.borderRadius='';}
  });}
  var h=w.querySelector('.win-header');
  (function(win,handle){
    var sx,sy,ox,oy,drag=false;
    handle.addEventListener('mousedown',function(e){
      if(e.target.tagName==='BUTTON')return;
      if(win.dataset.max==='1')return;
      drag=true;sx=e.clientX;sy=e.clientY;ox=win.offsetLeft;oy=win.offsetTop;
      document.addEventListener('mousemove',mv);document.addEventListener('mouseup',up);
    });
    function mv(e){if(!drag)return;win.style.left=(ox+e.clientX-sx)+'px';win.style.top=Math.max(0,(oy+e.clientY-sy))+'px';}
    function up(){drag=false;document.removeEventListener('mousemove',mv);document.removeEventListener('mouseup',up);}
  })(w,h);
});
function syncTaskbar(){
  var f=document.getElementById('files-window');var n=document.getElementById('notepad-window');
  document.getElementById('open-files').classList.toggle('active',f.style.display!=='none');
  document.getElementById('open-notepad').classList.toggle('active',n.style.display!=='none');
}
document.getElementById('open-files').addEventListener('click',function(){showWin(document.getElementById('files-window'));syncTaskbar();});
document.getElementById('open-notepad').addEventListener('click',function(){showWin(document.getElementById('notepad-window'));syncTaskbar();var ed=document.getElementById('editor');});
document.getElementById('desk-files').addEventListener('click',function(){showWin(document.getElementById('files-window'));syncTaskbar();});
document.getElementById('desk-notes').addEventListener('click',function(){showWin(document.getElementById('notepad-window'));syncTaskbar();});

/* clock */
function tick(){var d=new Date();var s=d.toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})+' '+d.toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'});document.getElementById('clock').textContent=s;}
tick();setInterval(tick,10000);

/* Files app */
var FS={
"/":[{name:"bin",type:"dir"},{name:"etc",type:"dir"},{name:"home",type:"dir"},{name:"usr",type:"dir"},{name:"var",type:"dir"},{name:"tmp",type:"dir"},{name:"opt",type:"dir"},{name:"README.txt",type:"file",content:"Welcome to Fake Ubuntu!\nDouble-click folders to browse."}],
"/home":[{name:"user",type:"dir"}],
"/home/user":[{name:"Documents",type:"dir"},{name:"Downloads",type:"dir"},{name:"Pictures",type:"dir"},{name:"notes.txt",type:"file",content:"My notes\n- buy milk\n- learn JS"},{name:"todo.txt",type:"file",content:"TODO:\n[ ] finish project"}],
"/home/user/Documents":[{name:"Projects",type:"dir"},{name:"report.txt",type:"file",content:"Annual report 2026"},{name:"ideas.md",type:"file",content:"# Ideas\n- build desktop in HTML"}],
"/home/user/Documents/Projects":[{name:"demo.txt",type:"file",content:"demo project"}],
"/home/user/Downloads":[{name:"ubuntu.iso",type:"file",content:"binary placeholder"},{name:"setup.sh",type:"file",content:"#!/bin/bash\necho hi"}],
"/home/user/Pictures":[{name:"wallpaper.png",type:"file",content:"image placeholder"},{name:"photo.jpg",type:"file",content:"photo placeholder"}],
"/bin":[{name:"bash",type:"file",content:"binary"},{name:"ls",type:"file",content:"binary"},{name:"cat",type:"file",content:"binary"}],
"/etc":[{name:"hosts",type:"file",content:"127.0.0.1 localhost"},{name:"passwd",type:"file",content:"root:x:0:0:user:/home/user:/bin/bash"}],
"/usr":[{name:"bin",type:"dir"},{name:"lib",type:"dir"},{name:"share",type:"dir"}],
"/usr/bin":[{name:"python3",type:"file",content:"binary"}],
"/usr/lib":[{name:"libc.so",type:"file",content:"binary"}],
"/usr/share":[{name:"docs",type:"dir"}],
"/usr/share/docs":[{name:"readme.txt",type:"file",content:"docs"}],
"/var":[{name:"log",type:"dir"},{name:"tmp",type:"dir"}],
"/var/log":[{name:"syslog",type:"file",content:"log..."}],
"/var/tmp":[],
"/tmp":[{name:"temp.txt",type:"file",content:"temp"}],
"/opt":[{name:"app",type:"dir"}],
"/opt/app":[{name:"run.sh",type:"file",content:"run"}]
};
var cur="/";
var listEl=document.getElementById('files-list');
var pathEl=document.getElementById('files-path');
var statusEl=document.getElementById('files-status');
function parentOf(p){if(p==="/")return "/";var i=p.lastIndexOf("/");if(i===0)return "/";return p.slice(0,i);}
function renderFiles(){
  pathEl.textContent=cur;
  listEl.innerHTML="";
  var items=FS[cur]||[];
  var sorted=items.slice().sort(function(a,b){if(a.type!==b.type)return a.type==="dir"?-1:1;return a.name.localeCompare(b.name);});
  sorted.forEach(function(it){
    var d=document.createElement('div');
    d.className='fs-item';d.textContent=it.name;
    d.dataset.name=it.name;d.dataset.type=it.type;
    d.setAttribute('title',it.name+(it.type==='dir'?' (folder)':' (file)'));
    d.addEventListener('click',function(e){e.stopPropagation();listEl.querySelectorAll('.fs-item').forEach(function(x){x.classList.remove('selected')});d.classList.add('selected');statusEl.textContent=it.name+(it.type==='dir'?' — folder, double-click to open':' — file, double-click to view');});
    d.addEventListener('dblclick',function(e){
      e.stopPropagation();
      if(it.type==='dir'){var np=cur==="/"?"/"+it.name:cur+"/"+it.name;cur=np;renderFiles();}
      else{statusEl.textContent=it.name+': '+(it.content||'(empty file)').slice(0,120);openFileInNotepad(it.name,it.content||"");}
    });
    listEl.appendChild(d);
  });
  if(sorted.length===0){statusEl.textContent='Empty folder — '+cur;}
  else if(statusEl.textContent==='Ready'||statusEl.textContent.indexOf('Empty')===0){statusEl.textContent=sorted.length+' item(s) — '+cur;}
  document.querySelectorAll('#files-sidebar button').forEach(function(b){b.classList.toggle('sel',b.dataset.go===cur);});
}
document.getElementById('files-up').addEventListener('click',function(){cur=parentOf(cur);renderFiles();});
document.getElementById('files-home').addEventListener('click',function(){cur='/home/user';renderFiles();});
document.getElementById('files-refresh').addEventListener('click',function(){renderFiles();});
document.querySelectorAll('#files-sidebar button').forEach(function(b){b.addEventListener('click',function(){cur=b.dataset.go;renderFiles();showWin(document.getElementById('files-window'));syncTaskbar();});});
listEl.addEventListener('click',function(){});
renderFiles();

/* Notepad app */
var KEY='notepad-tabs-v1';
var tabs=[];var activeId=null;var counter=1;
function saveTabs(){try{localStorage.setItem(KEY,JSON.stringify({tabs:tabs,activeId:activeId,counter:counter}));var st=document.getElementById('notepad-status');if(st)st.textContent='Saved '+new Date().toLocaleTimeString();}catch(e){}}
function loadTabs(){
  try{
    var raw=localStorage.getItem(KEY);
    if(raw){var o=JSON.parse(raw);if(o&&Array.isArray(o.tabs)&&o.tabs.length>0){tabs=o.tabs;activeId=o.activeId;counter=o.counter||o.tabs.length+1;if(!tabs.find(function(t){return t.id===activeId}))activeId=tabs[0].id;return;}}
  }catch(e){}
  tabs=[{id:'t1',title:'Untitled 1',content:''}];activeId='t1';counter=2;saveTabs();
}
var tabsEl=document.getElementById('tabs');
var editor=document.getElementById('editor');
function persistCurrentEditor(){var a=tabs.find(function(t){return t.id===activeId});if(a){if(a.content!==editor.value){a.content=editor.value;saveTabs();}}}
function renderTabs(){
  tabsEl.innerHTML="";
  tabs.forEach(function(t){
    var d=document.createElement('div');d.className='tab'+(t.id===activeId?' active':'');d.dataset.id=t.id;
    var label=document.createElement('span');label.className='tab-label';label.textContent=t.title||'Untitled';
    var x=document.createElement('button');x.className='tab-close';x.textContent='×';x.title='Close tab';
    x.addEventListener('click',function(e){
      e.stopPropagation();persistCurrentEditor();
      var idx=tabs.findIndex(function(z){return z.id===t.id});
      tabs.splice(idx,1);
      if(tabs.length===0){counter++;var nt={id:'t'+Date.now(),title:'Untitled '+counter,content:''};tabs.push(nt);activeId=nt.id;}
      else if(activeId===t.id){activeId=tabs[Math.max(0,idx-1)].id;}
      saveTabs();renderTabs();
    });
    d.appendChild(label);d.appendChild(x);
    d.addEventListener('click',function(){if(activeId!==t.id){persistCurrentEditor();activeId=t.id;saveTabs();renderTabs();}});
    d.addEventListener('dblclick',function(e){
      e.stopPropagation();
      var nn=prompt('Rename tab',t.title);
      if(nn!==null&&nn.trim()!==''){t.title=nn.trim().slice(0,30);saveTabs();renderTabs();}
    });
    tabsEl.appendChild(d);
  });
  var act=tabs.find(function(t){return t.id===activeId});
  editor.value=act?act.content:"";
}
editor.addEventListener('input',function(){var a=tabs.find(function(t){return t.id===activeId});if(a){a.content=editor.value;saveTabs();}});
document.getElementById('new-tab').addEventListener('click',function(){
  persistCurrentEditor();
  counter++;var nt={id:'t'+Date.now()+'_'+counter,title:'Untitled '+counter,content:''};
  tabs.push(nt);activeId=nt.id;saveTabs();renderTabs();editor.focus();
});
function openFileInNotepad(name,content){
  persistCurrentEditor();
  counter++;var nt={id:'t'+Date.now()+'_'+counter,title:name,content:content};
  tabs.push(nt);activeId=nt.id;saveTabs();renderTabs();showWin(document.getElementById('notepad-window'));syncTaskbar();
}
loadTabs();renderTabs();
window.addEventListener('beforeunload',function(){persistCurrentEditor();saveTabs();});
})();
</script>
</body>
</html>
